/* The Discover book — topic 1.2 (Frame the Technical Problem) */
export const chapter2: BookChapter = {
  id: "day-2", n: "2", day: 2, title: "Frame the Technical Problem", kicker: "Technical Framing Review",
  question: "What problem are we really solving, and what don’t we know?",
  intro: [
    { t: "p", text: "Topic 1.1 gave you the ground. This topic gives you the frame: a technical problem stated on its own, without the solution someone already had in mind; every unknown written as a hypothesis you could prove wrong; “good enough” defined in numbers; and a short plan of experiments for the scariest unknowns." },
    { t: "figure", fig: { kind: "hub", center: "Topic 1.2’s frame", items: [{ label: "Problem stated alone", icon: "description", text: "The technical problem, without the solution someone already had in mind." }, { label: "Unknowns as hypotheses", icon: "science", text: "Every unknown written as a hypothesis you could prove wrong." }, { label: "“Good enough” in numbers", icon: "speed", text: "Quality defined as targets with numbers." }, { label: "Plan of experiments", icon: "timer", text: "A short plan of experiments for the scariest unknowns." }] }, caption: "The four things this topic writes down. Notice that none of them is a design: each is something later work will be measured against." },
    { t: "p", text: "This topic is about writing rather than building, and that’s deliberate. Everything you write here is something later work will be measured against. The investigation in topic 1.3 works inside this frame. The options in topic 1.4 are compared against its targets. The decision in topic 1.5 is only as good as the questions you chose to answer first. A sloppy frame doesn’t fail loudly — it quietly lets the first idea win." },
    { t: "p", text: "The four lessons chain tightly. Each one’s output is the next one’s input, and each closes at its own small gate before the topic’s review." },
    { t: "table", caption: "The four lessons of this topic", head: ["Lesson", "What it produces", "Its gate", "Timebox"], rows: [
      ["1.2.1 Separate Problem from Proposed Solution", "Technical problem / solution split", "Problem Separated", "1–2 hours"],
      ["1.2.2 List Unknowns & Technical Hypotheses", "Technical hypothesis list, ranked", "Unknowns Ranked", "2–4 hours"],
      ["1.2.3 Set Quality Attributes & Success Metrics", "Quality attribute priorities and technical success metrics", "Targets Agreed", "2–4 hours"],
      ["1.2.4 Plan Time-boxed Discovery Spikes", "Spike plan and the technical framing pack", "Technical Framing Review", "1–2 hours"],
    ] },
    { t: "figure", fig: { kind: "ranges", unit: "hours", rows: [{ label: "1.2.1 Separate problem from solution", low: 1, high: 2 }, { label: "1.2.2 List unknowns & hypotheses", low: 2, high: 4 }, { label: "1.2.3 Set quality attributes & metrics", low: 2, high: 4 }, { label: "1.2.4 Plan time-boxed spikes", low: 1, high: 2 }] }, caption: "The timebox of each lesson. The two middle lessons get the most time; the first and last are short by design." },
    { t: "figure", fig: { kind: "flow", steps: [{ label: "System context pack", sub: "from topic 1.1", tone: "system" }, { label: "Problem / solution split", sub: "1.2.1", tone: "new" }, { label: "Ranked hypotheses", sub: "1.2.2", tone: "new" }, { label: "Quality targets & metrics", sub: "1.2.3", tone: "new" }, { label: "Spike plan & framing pack", sub: "1.2.4", tone: "new" }, { label: "Investigate", sub: "topic 1.3", tone: "human" }] }, caption: "How this topic runs: from the context pack you accepted in the previous topic to one framing pack that topic 1.3 works inside." },
    { t: "p", text: "You drive all four lessons with your coding agent beside you. It drafts the why-chains, the hypotheses, the scenarios and the spike designs quickly; you check every line against the evidence from topic 1.1; the tech lead decides what’s agreed." },
    { t: "figure", fig: { kind: "lanes", lanes: ["Agent", "You", "Tech lead"], steps: [{ lane: 0, label: "Drafts", sub: "why-chains, hypotheses, scenarios, spike designs" }, { lane: 1, label: "Checks every line", sub: "against topic 1.1’s evidence", flag: "manual" }, { lane: 2, label: "Decides what’s agreed", flag: "ok" }] }, caption: "Who does what in this topic, in every lesson: the agent drafts fast, you check against the evidence, the tech lead decides." },
    { t: "p", text: "The topic closes at the **Technical Framing Review**: the problem has no solution words in it, the hypotheses are falsifiable, the targets are numbers, and every spike is time-boxed with a success signal." },
    { t: "callout", tone: "key", title: "The question for this topic", text: "What problem are we really solving, and what don’t we know? If you can answer both in a page, with numbers and without naming a product, you’ve framed it." },
  ],
  sections: [
    /* ───────────────────────────── 1.2.1 ───────────────────────────── */
    {
      id: "discover.frame.separate", fid: "discover.frame.separate", code: "1.2.1", title: "Separate Problem from Proposed Solution", minutes: 12,
      blocks: [
        { t: "lead", text: "Somebody always has a solution before anyone has the problem. This lesson keeps that solution safe — and keeps it from becoming the design before anyone knows what it’s for." },
        { t: "tldr", items: [
          "Record every proposed solution word for word, with who proposed it. Never delete one.",
          "Ladder down from the solution with “why would that help?” until you hit a measurable condition in the system.",
          "State that condition in two or three sentences with no technology, product or vendor named, citing SYS, DF and INT evidence.",
          "The proposal survives as an option for topic 1.4, not as the plan.",
          "The tech lead reads the problem back and agrees it: that’s the Problem Separated gate.",
        ] },
        { t: "h", text: "Why it matters" },
        { t: "p", text: "That somebody might be the client, a manager, or you. The idea isn’t wrong to have — it’s wrong to *adopt* before you know what it’s for. This lesson stops the first solution anyone mentioned from becoming the design, by stating the technical problem on its own." },
        { t: "p", text: "The danger isn’t that the first idea is bad. Often it’s perfectly reasonable. The danger is that once it’s in the brief, everything after it is quietly shaped around it: the questions you ask, the data you look at, the options you bother to research. By topic 1.5 you’re “deciding” between the proposal and two straw men. The real concern this lesson guards against is simple: **building the proposed tool instead of fixing the problem.**" },
        { t: "figure", fig: { kind: "flow", steps: [{ label: "Proposal in the brief", tone: "human" }, { label: "Questions shaped around it", tone: "risk" }, { label: "Data shaped around it", tone: "risk" }, { label: "Options shaped around it", tone: "risk" }, { label: "Topic 1.5: proposal vs two straw men", tone: "risk" }] }, caption: "How an unexamined proposal quietly becomes the design. Nothing fails loudly; each step just narrows what you look at." },
        { t: "p", text: "The job: *help me make sure I’m fixing the real problem, not building the first idea someone had.*" },
        { t: "pull", text: "Recording the proposal shows you listened. Adopting it unexamined shows you didn’t think." },
        { t: "h", text: "Where it sits in Discover" },
        { t: "p", text: "This is the first lesson of the framing topic. It starts the moment the system context pack from topic 1.1 has been accepted — that’s its entry condition — and it hands one artifact, the technical problem / solution split, to the next lesson, where every unknown gets written as a hypothesis. Time-box it at one to two hours. If it’s taking longer, you’re probably arguing about solutions again." },
        { t: "table", caption: "Inputs, output and people", head: ["", "What"], rows: [
          ["In", "System context pack (accepted in topic 1.1); Client brief"],
          ["Out", "Technical problem / solution split"],
          ["Evidence", "Tech lead review notes"],
          ["A — accountable", "Tech lead: agrees the problem statement"],
          ["R — responsible", "Engineer: records, ladders, writes the split"],
          ["C — consulted", "The proposer of the solution"],
          ["I — informed", "Architect"],
          ["Gate", "Problem Separated"],
          ["Timebox", "1–2 hours"],
        ] },
        { t: "figure", fig: { kind: "context", center: { label: "Problem / solution split", sub: "1.2.1" }, around: [{ label: "System context pack", sub: "accepted in topic 1.1", type: "store", dir: "in" }, { label: "Client brief", type: "store", dir: "in" }, { label: "Engineer", sub: "responsible", type: "person", link: "records, ladders, writes", dir: "out" }, { label: "Tech lead", sub: "accountable", type: "person", link: "agrees the problem", dir: "both" }, { label: "Proposer", sub: "consulted", type: "person", link: "“have I got that right?”", dir: "both" }, { label: "Architect", sub: "informed", type: "person", dir: "out" }, { label: "1.2.2 List Unknowns", type: "system", link: "hands the split on", dir: "out" }] }, caption: "The split and everything around it. Notice the proposer is consulted, not overruled." },
        { t: "note", text: "The proposer is *consulted*, not overruled. You’re going back to them with “here’s what I think your idea is for — have I got that right?”, which is a very different conversation from “we’re not doing your idea”." },
        { t: "h", text: "Key ideas" },
        { t: "h3", text: "Problem / solution separation" },
        { t: "p", text: "The pattern is simple: write the requested solution in one place, exactly as asked, and the problem it implies in another, in solution-free words, so the problem can be checked on its own. The two live side by side in the same artifact. Neither replaces the other." },
        { t: "figure", fig: { kind: "split", left: { title: "The requested solution", tone: "guess", items: ["Written exactly as asked", "With who proposed it", "Kept, never deleted"] }, right: { title: "The problem it implies", tone: "fact", items: ["In solution-free words", "Checked on its own", "Points at system evidence"] } }, caption: "The two halves of the split live side by side in one artifact. Neither replaces the other." },
        { t: "h3", text: "Solution-to-problem laddering" },
        { t: "p", text: "You climb from “we need X” down through “so that…” and “because…” until a problem appears that names no solution. Each rung is one *why*. It usually takes three to five rungs. The technique is a close cousin of **Five Whys**, which comes from the Toyota Production System and is normally used to go from a symptom to its root cause. Here you’re using the same questioning in a different direction: from a solution to the failure it would fix." },
        { t: "figure", fig: { kind: "knowledge", name: "Solution-to-problem laddering" }, caption: "Solution-to-problem laddering: from “we need X”, through what it enables and what that fixes, to the underlying problem." },
        { t: "h3", text: "Causes over symptoms, and understanding before solving" },
        { t: "p", text: "Two principles sit behind the ladder. *Causes over symptoms*: a complaint is a symptom, so keep asking until you reach something in the system that produces it. *Understand before solving*: don’t design anything until the context and constraints are understood. In this topic you already have that context — the system context pack — so every rung of the ladder can be checked against it." },
        { t: "h3", text: "Where the problem lands: functional suitability" },
        { t: "p", text: "In ISO/IEC 25010 terms, the problem you state here is usually about *functional suitability*: the system doesn’t do something it needs to, or does it only with a person in the loop. Saying it in those terms helps later, when 1.2.3 turns it into measurable quality targets. It also echoes the first section of an arc42 architecture document, *introduction and goals*: what the system is for, before how it’s built." },
        { t: "terms", items: [
          { term: "Proposed solution", def: "Any specific product, technology, tool or design someone has asked for. Recorded verbatim, with who proposed it." },
          { term: "Why-chain (ladder)", def: "A short sequence of “why would that help?” answers, one per line, from the proposal down to a condition in the system." },
          { term: "Solution words", def: "Any word that names a technology, product, vendor or approach — “AI”, “OCR”, “microservice”, “dashboard”. None may remain in the problem statement." },
          { term: "System condition", def: "Something that fails, measurably, in the system today — and can be pointed at with topic 1.1’s SYS, DF or INT IDs." },
          { term: "Mandated technology", def: "A solution the client requires, not just prefers. It becomes a constraint, and the problem is framed as how to make it work, not whether." },
        ] },
        { t: "figure", fig: { kind: "hub", center: "Separating problem from solution", items: [{ label: "Proposed solution", icon: "record_voice_over", text: "Any product, technology, tool or design someone asked for — recorded verbatim, with who proposed it." }, { label: "Why-chain", icon: "route", text: "“Why would that help?” answers, one per line, down to a condition in the system." }, { label: "Solution words", icon: "block", text: "“AI”, “OCR”, “microservice”, “dashboard” — none may remain in the problem." }, { label: "System condition", icon: "report", text: "Something that fails measurably today, pointed at with SYS, DF or INT IDs." }, { label: "Mandated technology", icon: "gavel", text: "Required by the client, not just preferred — it becomes a constraint." }] }, caption: "The five terms of this lesson. The why-chain is the bridge: it starts at a proposed solution and must end at a system condition." },
        { t: "h", text: "How to do it" },
        { t: "steps", items: [
          { title: "Record the proposed solution as asked", text: "Word for word, with who proposed it. Go back to the brief and your notes from topic 1.1 and pull out every proposal, however casual — a line in an email counts. Don’t paraphrase, don’t tidy the grammar, don’t judge. You aren’t dismissing it; you’re putting it somewhere safe. It will come back later as one of the options. The policy here is plain: proposals are recorded verbatim.", tip: "If no one proposed a solution, that’s a valid route too: write the problem straight from the system context pack and skip the ladder." },
          { title: "Ladder from the solution to the failure", text: "Ask *why would that help?* — and then why again — until you reach a condition in the system: something that fails, measurably, today. Write one rung per line. At each rung, check the answer against the system context pack: is there a SYS, DF or INT entry that shows this is true? This is solution-to-problem laddering, and it usually takes three to five rungs. Stop when no tool or product is named and the line describes the system, not the wish.", tip: "Run the why-chain while you re-read the context pack, not from memory. The pack keeps the ladder honest." },
          { title: "State the problem without solution words", text: "Write two or three sentences: *what fails, where in the flow, and what would show it’s fixed*. No product, no technology, no vendor. Point it at the evidence from topic 1.1 — the system, data-flow and integration IDs — and link it back to the request (REQ-###). Then add a short “what would prove we fixed it” line in observable signs, not features. Finally, list the original proposal as one option, marked for the option research in topic 1.4.", tip: "Read the statement as if you’d never heard the proposal. Would it lead you to the proposal and nothing else? Then a solution is still hiding in it." },
          { title: "Decide: is the problem stated without a solution?", text: "Read it back to the tech lead. Check two things: no technology or product is named, and the problem points at system evidence. If solution words remain, ladder again. If a technology is genuinely mandated, that’s a constraint for the client to confirm. If the proposer rejects the reframing, the tech lead decides. And if there’s no technical problem underneath at all — it’s really a process fix — stop and say so, and record it in the learning log.", tip: "A useful read-back test: would two engineers read this problem the same way?" },
        ] },
        { t: "figure", fig: { kind: "workflow", fid: "discover.frame.separate" }, caption: "Split Problem from Solution — record, ladder, state, and the tech lead’s check, with its loops back to laddering and out to the client." },
        { t: "contrast", label: "A problem statement", bad: { title: "Solution in disguise", text: "“We need an intelligent document-processing pipeline so orders are entered automatically.” It names an approach, assumes the answer, and gives you nothing to measure." }, good: { title: "Solution-free, evidence-backed", text: "“Order data arrives unstructured (DF-01) and reaches the ERP only by manual re-keying (DF-02), so throughput is capped by clerk time and errors enter at DF-02.” It says what fails, where, and points at the evidence." } },
        { t: "figure", fig: { kind: "anatomy", parts: [{ text: "Order data arrives unstructured", label: "What fails" }, { text: " (DF-01)", label: "Evidence", note: "A topic 1.1 data flow ID." }, { text: " and reaches the ERP only by manual re-keying", label: "Where in the flow" }, { text: " (DF-02)", label: "Evidence" }, { text: ", so throughput is capped by clerk time and errors enter at DF-02.", label: "What it costs", note: "No technology, product or vendor is named anywhere." }] }, caption: "The solution-free statement, taken apart. Every claim points at a topic 1.1 ID, and no tool appears in it." },
        { t: "callout", tone: "warn", title: "Never delete the proposed solution", text: "It becomes an option you’ll evaluate later. Deleting it tells its proposer you didn’t listen; adopting it means you didn’t think. Recording it does neither." },
        { t: "h", text: "The case: Northwind" },
        { t: "p", text: "Northwind’s brief arrives with a solution already in it. The operations lead wants to “use an AI tool to read the PDFs and push them into the ERP”. That sentence goes into the split exactly as written, with the operations lead’s name beside it." },
        { t: "figure", fig: { kind: "ladder", top: "“Use an AI tool to read the PDFs”", bottom: "Orders arrive unstructured and reach the ERP only by re-keying", rungs: ["Why? — so nobody has to read the PDFs by hand", "Why does that matter? — clerks re-type every line into the ERP", "Why do they re-type? — the order isn’t in a form the ERP can take"] }, caption: "Laddering from the proposed solution down to the condition in the system. The top rung is kept — as an option, not as the design." },
        { t: "p", text: "The ladder in the split runs like this. Why AI? To read the PDFs. Why read them? Because clerks re-type every line. Why re-type? Because the ERP only takes structured orders through its API. Why is that a problem? Fourteen minutes an order and 3% errors. Each rung is checked against topic 1.1: the ERP’s import API is a hard constraint from the admin guide, and the re-keying step is a named data flow." },
        { t: "table", caption: "Northwind’s problem / solution split (REQ-014)", head: ["Part", "What Northwind wrote"], rows: [
          ["The proposed solution, as asked", "“Use an AI tool to read the PDFs and push them into the ERP” — operations lead"],
          ["The problem, without solution words", "Order data arrives unstructured (DF-01) and reaches the ERP only by manual re-keying (DF-02), so throughput is capped by clerk time and errors enter at DF-02."],
          ["What would prove we fixed it", "Orders reach the ERP import API without re-keying; clerk minutes and entry errors per order fall."],
          ["The proposal, kept as an option", "AI/OCR parsing → listed as an option candidate for 1.4"],
        ] },
        { t: "callout", tone: "case", title: "Northwind", text: "“Use an AI tool” is recorded verbatim and set aside; the why-chain ends at the real condition: orders arrive unstructured and reach the ERP only by re-keying." },
        { t: "p", text: "Notice what the reframing opens up. “Orders arrive unstructured” could be fixed by reading PDFs better — the operations lead’s idea — but the frame doesn’t rule out other routes, and topic 1.4 is where they get compared. Nothing has been rejected. The problem has simply stopped being a shopping list." },
        { t: "figure", fig: { kind: "template", id: "technical-problem-split" }, caption: "The problem / solution split — the proposal as asked, the why-chain, the problem it implies, and what would prove it." },
        { t: "h", text: "Working with your agent" },
        { t: "p", text: "Laddering is a good job for an agent: it’s patient, it doesn’t get bored of asking why, and it doesn’t mind being told its rung is wrong. What it can’t do is know which rungs are true. It will happily reason its way to a plausible problem nobody has observed. So you give it the context pack, you make it cite IDs, and you check every citation." },
        { t: "prompt", title: "Record and ladder", text: "From the client brief and my notes, write down every solution anyone has proposed, word for word, with who proposed it. Don’t judge or rephrase them yet.\n\nThen, for the main proposal, build a why-chain: ask what it’s for, then why that matters, one line at a time, until you reach a condition in the system. Cite the SYS, DF or INT IDs from my system context pack on every rung. Stop when no tool or product is named." },
        { t: "p", text: "Check its answer: every proposal really appears in the brief or your notes, quoted exactly; every rung cites an ID that exists in your pack and says what that entry says; the last rung describes something that fails today, not a wish. Delete any rung the agent couldn’t back with evidence." },
        { t: "prompt", title: "State it and check it", text: "State the problem in two or three sentences with no technology, product or vendor named — what fails, where in the flow, and what would show it’s fixed. Then list the original proposal as one option for later.\n\nFinally, check the statement for hidden solution words and for any claim not supported by my system context pack, and list what you find." },
        { t: "p", text: "Check its answer: scan the statement yourself for solution words — agents often let “automated”, “digital” or “intelligent” slip through. Confirm the original proposal is still listed, word for word. Then take it to the tech lead; the agent’s self-check is a draft, not the read-back." },
        { t: "figure", fig: { kind: "lanes", lanes: ["You", "Agent", "Tech lead"], steps: [{ lane: 0, label: "Give it the context pack", sub: "and the brief and notes" }, { lane: 1, label: "Records every proposal", sub: "word for word, with who proposed it" }, { lane: 1, label: "Builds the why-chain", sub: "citing SYS, DF or INT IDs" }, { lane: 0, label: "Check every citation", sub: "delete rungs without evidence", flag: "manual" }, { lane: 1, label: "States the problem, self-checks", sub: "for solution words" }, { lane: 0, label: "Scan for solution words yourself", flag: "manual" }, { lane: 2, label: "Read-back and agreement", flag: "ok" }] }, caption: "Working the split with your agent. The agent’s self-check is a draft; the read-back belongs to the tech lead." },
        { t: "callout", tone: "agent", title: "With your agent", text: "Ask your agent to play the five-year-old: “why would that help?” at every rung, stopping only at something measurable in the system. Then check the last rung against topic 1.1’s evidence — the agent will happily reason its way to a problem nobody has observed." },
        { t: "h", text: "Common mistakes" },
        { t: "pitfalls", items: [
          { trap: "The proposed tool is restated as the problem: “the problem is we don’t have an AI tool”.", fix: "Ask “what goes wrong today without it?” until no tool is named." },
          { trap: "The original proposal is lost or rewritten in your own words.", fix: "Restore the verbatim proposal from the brief, with who proposed it." },
          { trap: "Stopping at exactly five whys because that’s the name of the technique.", fix: "Stop when you reach a condition in the system you can measure — sometimes that’s three rungs, sometimes six." },
          { trap: "Rungs that sound right but aren’t in the evidence.", fix: "Only evidence from the system context pack counts. Cite an ID on every rung or cut the rung." },
          { trap: "Treating a strong preference as a mandate.", fix: "Only the client can make a technology mandatory. Ask them; until they confirm, it’s an option." },
        ] },
        { t: "figure", fig: { kind: "fishbone", effect: "A tool-shaped problem", bones: [{ label: "Statement", causes: ["Proposed tool restated as the problem"] }, { label: "Record", causes: ["Proposal lost or rewritten in your words"] }, { label: "Ladder", causes: ["Stopping at exactly five whys", "Rungs not in the evidence"] }, { label: "Mandate", causes: ["Strong preference treated as a mandate"] }] }, caption: "The common mistakes, grouped by where they happen. Each one lets a tool slip back into the problem." },
        { t: "h", text: "When it goes off the path" },
        { t: "p", text: "Most of the time the happy path holds: the proposal maps to one clear technical problem the tech lead recognises. When it doesn’t, the routes are already written down." },
        { t: "table", caption: "Routes out of the decision", head: ["Situation", "What you do", "Who decides"], rows: [
          ["Problem stated cleanly", "Hand the split to 1.2.2 List Unknowns & Technical Hypotheses", "Tech lead"],
          ["Solution words remain", "Ladder again", "Engineer"],
          ["No solution was proposed", "Write the problem straight from the system context pack", "Engineer"],
          ["Several solutions proposed", "One row each — you’ll usually find the same problem underneath", "Engineer"],
          ["Technology is mandated", "Record it as a constraint; frame the problem as “make X work here” — how, not whether", "Client"],
          ["Proposer rejects the reframing", "Escalate", "Tech lead"],
          ["No technical problem underneath (a process fix)", "Stop and say so; record it in the learning log", "Tech lead"],
        ] },
        { t: "figure", fig: { kind: "decide", start: "q1", nodes: [{ id: "q1", q: "Was any solution proposed?", yes: "q2", no: "r1" }, { id: "r1", result: "Write the problem straight from the system context pack. Engineer.", tone: "neutral" }, { id: "q2", q: "Has the client mandated the technology?", yes: "r2", no: "q3" }, { id: "r2", result: "Record it as a constraint; frame the problem as “make X work here”. Client.", tone: "neutral" }, { id: "q3", q: "Is there a technical problem underneath?", yes: "q4", no: "r3" }, { id: "r3", result: "Stop and say so; record it in the learning log. Tech lead.", tone: "bad" }, { id: "q4", q: "Do solution words remain in the statement?", yes: "r4", no: "q5" }, { id: "r4", result: "Ladder again. Engineer.", tone: "neutral" }, { id: "q5", q: "Does the proposer accept the reframing?", yes: "r6", no: "r5" }, { id: "r5", result: "Escalate. Tech lead decides.", tone: "neutral" }, { id: "r6", result: "Hand the split to 1.2.2 List Unknowns & Technical Hypotheses. Tech lead.", tone: "good" }] }, caption: "Walk the routes out of the Problem Separated decision. Several proposals don’t change the path: give each its own row." },
        { t: "p", text: "The one real failure is a problem that can’t be stated without naming a tool. That usually means the ladder stopped too early, or that the request really is “install product X” with no failure behind it. Either ladder further, or route it as a mandate or a stop — don’t carry a tool-shaped problem into the hypotheses." },
        { t: "figure", fig: { kind: "knowledge", name: "Five Whys" }, caption: "Five Whys — the questioning behind the ladder. You stop at a cause you can act on, not at the fifth answer." },
        { t: "good", items: ["No technology or product named in the problem", "The problem points at system evidence (SYS, DF, INT IDs) and links to the REQ", "The proposed solution is recorded verbatim, with who proposed it, and kept as an option", "“What would prove we fixed it” is written in observable signs, not features", "The tech lead has read it back and agreed it"] },
        { t: "h", text: "Before you move on" },
        { t: "checklist", title: "Problem Separated", items: [
          "Every proposed solution is recorded word for word, with who proposed it",
          "The why-chain ends at a condition in the system, not a tool",
          "Every rung cites evidence from the system context pack",
          "The problem statement names no technology, product or vendor",
          "The proposal is listed as an option for topic 1.4",
          "The tech lead has read the problem back and agreed it",
        ] },
        { t: "try", text: "Write a why-chain from “use AI to read the PDFs” down to a system condition, then state the problem with no technology named. Then do the same for your own project." },
      ],
    },
    /* ───────────────────────────── 1.2.2 ───────────────────────────── */
    {
      id: "discover.frame.unknowns", fid: "discover.frame.unknowns", code: "1.2.2", title: "List Unknowns & Technical Hypotheses", minutes: 11,
      blocks: [
        { t: "lead", text: "You don’t know everything, and that’s fine. What isn’t fine is spending discovery on the easy questions while the one that could sink the project waits until week six." },
        { t: "tldr", items: [
          "Gather every open question and every low- or medium-confidence assumption into one list.",
          "Rewrite each as “We believe… We’re wrong if…”, with a concrete result that would prove it wrong. One unknown per hypothesis.",
          "Rate each on impact (how badly being wrong hurts) and uncertainty (how little evidence you have), and rank.",
          "Say how each will be tested: spike, measure, ask or docs.",
          "The tech lead agrees the top three: that’s the Unknowns Ranked gate.",
        ] },
        { t: "h", text: "Why it matters" },
        { t: "p", text: "This lesson makes every technical unknown explicit and testable, then ranks them so you know which to answer first." },
        { t: "p", text: "Two things go wrong without it. First, people answer the questions that are pleasant to answer — the ones with a document to read or a colleague to ask — and leave the frightening ones for later. Second, unknowns stay vague. “We’re not sure about performance” can never be resolved, because nothing could ever settle it. The concerns this lesson guards against are exactly those: **spending discovery on the easy questions**, and **hidden show-stoppers**." },
        { t: "figure", fig: { kind: "split", left: { title: "Without the list", tone: "bad", items: ["Pleasant questions answered first", "Frightening ones left for later", "Unknowns stay vague and can’t be settled"] }, right: { title: "With the list", tone: "good", items: ["Every unknown explicit and testable", "Ranked, so the riskiest is answered first", "Show-stoppers surface early"] } }, caption: "What this lesson changes. Vague worries can never be resolved; ranked, testable hypotheses can." },
        { t: "p", text: "The job: *help me know what could sink this technically, and which question to answer first.*" },
        { t: "pull", text: "If you can’t say what result would prove you wrong, you don’t have a hypothesis yet — you have a hope." },
        { t: "h", text: "Where it sits in Discover" },
        { t: "p", text: "This lesson starts when the problem / solution split has been agreed. It takes three inputs: the split itself, and the two logs you kept in topic 1.1 — the technical question log and the technical constraint log. It produces one list, the technical hypothesis list, which 1.2.3 uses to decide what “good” must mean and 1.2.4 uses to choose what to test. Time-box it at two to four hours." },
        { t: "table", caption: "Inputs, output and people", head: ["", "What"], rows: [
          ["In", "Technical problem / solution split; Technical question log; Technical constraint log"],
          ["Out", "Technical hypothesis list (H-##, each linked to a Q-## or A-##)"],
          ["Evidence", "Tech lead review notes"],
          ["A — accountable", "Tech lead: agrees the ranking"],
          ["R — responsible", "Engineer: collects, writes and rates"],
          ["C — consulted", "Architect"],
          ["I — informed", "Client contact"],
          ["Gate", "Unknowns Ranked"],
          ["Timebox", "2–4 hours"],
        ] },
        { t: "figure", fig: { kind: "context", center: { label: "Technical hypothesis list", sub: "H-##" }, around: [{ label: "Problem / solution split", type: "store", dir: "in" }, { label: "Technical question log", sub: "Q-##", type: "store", dir: "in" }, { label: "Technical constraint log", sub: "A-##", type: "store", dir: "in" }, { label: "Engineer", sub: "responsible", type: "person", link: "collects, writes, rates", dir: "out" }, { label: "Tech lead", sub: "accountable", type: "person", link: "agrees the ranking", dir: "both" }, { label: "Architect", sub: "consulted", type: "person", dir: "both" }, { label: "Client contact", sub: "informed", type: "person", dir: "out" }, { label: "1.2.3 Quality targets", type: "system", link: "decides what “good” must mean", dir: "out" }, { label: "1.2.4 Spike plan", type: "system", link: "chooses what to test", dir: "out" }] }, caption: "Three inputs in, one list out — and that list feeds both of the topic’s remaining lessons." },
        { t: "h", text: "Key ideas" },
        { t: "h3", text: "Make beliefs falsifiable" },
        { t: "p", text: "A belief is falsifiable when some result you could actually observe would show it’s wrong. “The ERP is probably fine” can’t fail. “The ERP import API sustains 160 orders an hour; we’re wrong if sustained throughput in test is below that” can. Falsifiable hypotheses are useful precisely because they can lose: a test either leaves them standing or knocks them over, and both outcomes teach you something." },
        { t: "h3", text: "Hypothesis-driven development" },
        { t: "p", text: "The method treats every idea as a hypothesis with a test and a measurable success signal: write the hypothesis, choose the signal, run the smallest test, decide on the evidence. In this topic you do the first two parts. The spike plan in 1.2.4 does the third, and topic 1.3 onwards does the fourth." },
        { t: "figure", fig: { kind: "cycle", center: "Hypothesis-driven", steps: [{ label: "Write the hypothesis", text: "Here, in this lesson." }, { label: "Choose the signal", text: "Here, in this lesson." }, { label: "Run the smallest test", text: "Planned in 1.2.4’s spike plan." }, { label: "Decide on the evidence", text: "Topic 1.3 onwards." }] }, caption: "The four moves of hypothesis-driven development, and which topic does each. This topic covers the first two." },
        { t: "figure", fig: { kind: "knowledge", name: "Hypothesis-driven development" }, caption: "Hypothesis-driven development: belief, test, signal, decision." },
        { t: "h3", text: "Assumption logs, maps and mapping" },
        { t: "p", text: "Your constraint log is already an *assumption log*: each assumption with its source, confidence and how you’d validate it. *Assumption mapping* plots those beliefs on two axes — how important they are, and how much evidence you have — so you can see which to test first. Lean Product Discovery, the framework behind it, says the same thing in one line: rank assumptions by what would kill the idea if wrong, then pick the cheapest test that exposes the riskiest one." },
        { t: "p", text: "In this lesson the two axes are named for engineering: **impact** (how badly would it hurt if we’re wrong?) and **uncertainty** (how little evidence do we have?). The riskiest hypotheses sit top right: high on both." },
        { t: "h3", text: "Covering the quality model" },
        { t: "p", text: "ISO/IEC 25010 is a useful prompt for what you might be missing. Have you an unknown about performance efficiency? Reliability? Security? Compatibility with the systems you integrate with? You don’t need one of each, but a list with nothing about security or volume is usually a list with blind spots, not a system without risks." },
        { t: "figure", fig: { kind: "hub", center: "Blind-spot check: ISO/IEC 25010", items: [{ label: "Performance efficiency", icon: "speed", text: "Have you an unknown about speed or volume?" }, { label: "Reliability", icon: "verified", text: "Have you an unknown about what happens when things fail?" }, { label: "Security", icon: "security", text: "A list with nothing about security usually has a blind spot." }, { label: "Compatibility", icon: "integration_instructions", text: "Have you an unknown about the systems you integrate with?" }] }, caption: "Use the quality model as a prompt, not a form. You don’t need one unknown for each — but an empty corner is worth a second look." },
        { t: "terms", items: [
          { term: "Unknown", def: "Any open technical question or unproven assumption: a Q-## still open, or an A-## with low or medium confidence." },
          { term: "Technical hypothesis (H-##)", def: "One unknown written as “We believe… We’re wrong if…”, linked back to the Q-## or A-## it came from." },
          { term: "Falsifiable", def: "There’s a concrete, observable result that would prove the belief wrong." },
          { term: "Impact", def: "How badly the build would be hurt if the hypothesis turned out to be wrong. High, Medium or Low." },
          { term: "Uncertainty", def: "How little evidence you have for it today. High means you’re mostly guessing." },
          { term: "Test route", def: "How the hypothesis will be answered: a spike, a measurement, asking an owner, or reading the docs." },
        ] },
        { t: "h", text: "How to do it" },
        { t: "steps", items: [
          { title: "Collect the unknowns from the logs", text: "Open the question log, the constraint log and the problem split side by side. Take every question still marked Open or Needs a spike, and every assumption with low or medium confidence, into one list. Add anything the problem split raised — the “what would prove we fixed it” line often hides an unknown. The policy is that assumptions from the constraint log are carried, not dropped: if it was a guess in topic 1.1, it’s still a guess here until something proves it.", tip: "Don’t filter yet. Collecting and judging at the same time is how the frightening ones get left out." },
          { title: "Write each one as a falsifiable hypothesis", text: "A hypothesis says what you believe *and what result would prove it wrong*: “We believe X. We’re wrong if Y.” Make Y concrete — a number, a sample, an environment. If you can’t write the “wrong if”, it isn’t a hypothesis yet; it’s either a vague worry that needs sharpening or a question that a document could simply answer. Keep the link to its source: every H-## points at a Q-## or A-##.", tip: "If you find “and” in the belief, you probably have two hypotheses. Split them." },
          { title: "Rate impact and uncertainty", text: "How badly would being wrong hurt? How sure are you? Rate each High, Medium or Low, with a one-line reason. Rate volume and speed unknowns honestly, don’t leave security unknowns to the end, and rate data-quality unknowns by their impact rather than how dull they sound. Then rank: the riskiest hypotheses are high on both. Finally, name a test route for each — spike, measure, ask or docs.", tip: "Uncertainty is about evidence, not about how confident you *feel*. “The clerk lead said so” is low evidence." },
          { title: "Decide: are the riskiest unknowns agreed?", text: "Prepare the top three for the tech lead, each with a one-line case for why it could sink the build. Ask the architecture question: are these the ones that could change the architecture? If a hypothesis can’t be falsified, rewrite it. If the team disagrees on the ranking, the tech lead decides. When the top three are agreed, the list goes on to 1.2.3.", tip: "The exit condition is precise: every unknown written as a falsifiable hypothesis, and the top three agreed with the tech lead." },
        ] },
        { t: "figure", fig: { kind: "workflow", fid: "discover.frame.unknowns" }, caption: "Rank the Unknowns — collect, write, rate, and the tech lead’s agreement, with the loop back to rewriting." },
        { t: "contrast", label: "A hypothesis", bad: { title: "Can’t fail", text: "“OCR should be accurate enough for our needs.” Accurate on what? Enough by whose measure? No result could ever prove it wrong, so no test could ever settle it." }, good: { title: "Can fail", text: "“We believe off-the-shelf OCR reads ≥ 95% of order lines correctly on our PDFs. We’re wrong if line accuracy is below 95% on a 200-PDF sample.” A number, a sample, and a result that would knock it over." } },
        { t: "figure", fig: { kind: "anatomy", parts: [{ text: "We believe " }, { text: "off-the-shelf OCR reads ≥ 95% of order lines correctly on our PDFs", label: "The belief", note: "One unknown only — no “and”." }, { text: ". We’re wrong if " }, { text: "line accuracy is below 95%", label: "The result that knocks it over", note: "A number you could actually observe." }, { text: " on a " }, { text: "200-PDF sample", label: "The sample" }, { text: "." }] }, caption: "A falsifiable hypothesis, part by part. Without the “wrong if” half, nothing could ever settle it." },
        { t: "callout", tone: "tip", title: "One unknown per hypothesis", text: "“The parser is accurate and fast enough” is two hypotheses wearing one coat. Split them — they’ll need different tests." },
        { t: "h", text: "The case: Northwind" },
        { t: "p", text: "Northwind’s logs from topic 1.1 already hold the raw material. The question log has Q-01 (how the ERP accepts orders — answered: through its REST import API only), Q-02 (what share of PDFs are scans versus generated — marked as needing a spike) and Q-03 (where customer codes live — still open). The constraint log holds A-01: the clerk lead’s verbal belief that 80% of order PDFs are machine-generated, rated low confidence." },
        { t: "figure", fig: { kind: "tree", root: "Northwind’s topic 1.1 logs", children: [{ label: "Technical question log", children: [{ label: "Q-01 How the ERP accepts orders", text: "Answered: REST import API only — a fact, captured as C-01." }, { label: "Q-02 Scans vs generated PDFs", text: "Marked as needing a spike." }, { label: "Q-03 Where customer codes live", text: "Still open." }] }, { label: "Technical constraint log", children: [{ label: "A-01 80% of PDFs machine-generated", text: "The clerk lead’s verbal belief — low confidence." }] }] }, caption: "The raw material for Northwind’s hypotheses. Q-01 is answered, so it stays a fact; the open questions and the low-confidence assumption are carried forward." },
        { t: "p", text: "Q-01 is answered, so it isn’t a hypothesis — it’s a fact, already captured as the hard constraint C-01. The others become three hypotheses." },
        { t: "table", caption: "Northwind’s technical hypotheses (REQ-014)", head: ["H", "We believe…", "We’re wrong if…", "From", "Impact", "Uncertainty", "Rank", "Test"], rows: [
          ["H-01", "Off-the-shelf OCR reads ≥ 95% of order lines correctly on our PDFs", "Line accuracy < 95% on a 200-PDF sample", "A-01, Q-02", "High", "High", "1", "Spike"],
          ["H-02", "The ERP import API sustains peak volume (≈160 orders/h)", "Sustained throughput < 160/h in test", "Q-01", "High", "Medium", "2", "Spike"],
          ["H-03", "Customer codes can be matched from the e-mail sender", "Match rate < 90% on the inbox sample", "Q-03", "Medium", "High", "3", "Measure"],
        ] },
        { t: "figure", fig: { kind: "matrix", x: "Uncertainty →", y: "Impact if wrong →", points: [{ label: "H-01 OCR accuracy", x: 0.85, y: 0.88 }, { label: "H-02 ERP throughput", x: 0.5, y: 0.82 }, { label: "H-03 customer matching", x: 0.82, y: 0.48 }] }, caption: "Impact × uncertainty. Spend discovery where both are high — top right first. H-01 is high on both; H-02 hurts badly but you know more; H-03 is uncertain but less damaging." },
        { t: "callout", tone: "case", title: "Northwind", text: "H-01 OCR accuracy on our PDFs, H-02 ERP throughput at peak, H-03 customer matching — ranked by impact and uncertainty." },
        { t: "p", text: "Look at how the ranking reads. H-01 comes first because if off-the-shelf reading can’t cope with Northwind’s PDFs, the operations lead’s option — still sitting in the split — loses its footing. H-02 matters as much if wrong, but you have more to go on: the API is documented. H-03 is a real unknown but a smaller one, and it can be answered by measuring a sample rather than building anything." },
        { t: "figure", fig: { kind: "template", id: "technical-hypotheses" }, caption: "The technical hypothesis list, ranked — each row traced to the question or assumption it came from, with its test route." },
        { t: "h", text: "Working with your agent" },
        { t: "p", text: "Turning a messy log into crisp “we believe / we’re wrong if” lines is exactly the kind of rewriting an agent does well and fast. Ranking is not. The agent can’t feel what being wrong would cost this client, and it will tend to rate everything Medium to be safe. You do the ranking; it does the drafting and the challenge." },
        { t: "prompt", title: "Collect and rewrite", text: "Collect every open question from my technical question log and every low- or medium-confidence assumption from my technical constraint log into one list. Keep each one’s ID.\n\nRewrite each unknown as a hypothesis — “We believe … ; we’re wrong if …” — with a concrete result that would prove it wrong. One unknown per hypothesis. Keep the link to the Q or A it came from." },
        { t: "p", text: "Check its answer: nothing was dropped from either log (count them); every “wrong if” is something you could actually observe, with a number and a sample or environment; no hypothesis contains two beliefs joined by “and”; answered questions haven’t been turned back into hypotheses." },
        { t: "prompt", title: "Rate, route and challenge", text: "Rate each hypothesis on impact (how badly it would hurt if wrong) and uncertainty (how little evidence we have), with a one-line reason for each rating. Say how each could be tested: spike, measure, ask or docs.\n\nThen prepare the top three for the tech lead with a one-line case for why each could sink the build — and tell me which of my ratings you’d challenge, and why." },
        { t: "p", text: "Check its answer: the reasons cite real evidence (or the lack of it), not general feelings; security and volume unknowns weren’t quietly rated Low; the proposed test routes are realistic for your environments. Then rank the list yourself before you take it to the tech lead." },
        { t: "figure", fig: { kind: "lanes", lanes: ["Agent", "You", "Tech lead"], steps: [{ lane: 0, label: "Collects every unknown", sub: "from both logs, IDs kept" }, { lane: 0, label: "Rewrites as hypotheses", sub: "we believe… we’re wrong if…" }, { lane: 1, label: "Count: nothing dropped", sub: "no “and”, no answered questions", flag: "manual" }, { lane: 0, label: "Rates, routes, challenges", sub: "one-line reason each" }, { lane: 1, label: "Rank the list yourself", flag: "manual" }, { lane: 2, label: "Agrees the top three", flag: "ok" }] }, caption: "The agent drafts and challenges; the ranking stays with you. It tends to rate everything Medium to be safe." },
        { t: "callout", tone: "agent", title: "With your agent", text: "Ask your agent to turn every open question and assumption into “We believe… We’re wrong if…”, and to rate impact and uncertainty with a one-line reason. Rank them yourself — the agent can’t feel what being wrong would cost this client." },
        { t: "h", text: "Common mistakes" },
        { t: "pitfalls", items: [
          { trap: "Hypotheses that can’t fail: “the integration should work”.", fix: "Add “we are wrong if…” to each, with a concrete, observable result." },
          { trap: "Easy questions ranked first because they’re quick to close.", fix: "Re-rate on impact × uncertainty. Ease of testing is a reason to test cheaply, not to test first." },
          { trap: "Two unknowns in one hypothesis.", fix: "One unknown per hypothesis. Split on every “and”." },
          { trap: "Dropping a low-confidence assumption because it feels unlikely to matter.", fix: "Assumptions from the constraint log are carried, not dropped. Rate it Low impact if you must — but keep it." },
          { trap: "Waiting for production to answer an unknown.", fix: "Find the nearest safe proxy: a masked sample, a test tenant, a load test against a copy." },
        ] },
        { t: "figure", fig: { kind: "fishbone", effect: "Hidden show-stoppers", bones: [{ label: "Writing", causes: ["Hypotheses that can’t fail", "Two unknowns in one"] }, { label: "Ranking", causes: ["Easy questions ranked first"] }, { label: "Carrying", causes: ["Low-confidence assumption dropped"] }, { label: "Testing", causes: ["Waiting for production to answer"] }] }, caption: "Each common mistake lets a real risk hide until later. Most of them happen while writing and ranking, not testing." },
        { t: "h", text: "When it goes off the path" },
        { t: "table", caption: "Routes out of the decision", head: ["Situation", "What you do", "Who decides"], rows: [
          ["Top three agreed", "Hand the list to 1.2.3 Set Quality Attributes & Success Metrics", "Tech lead"],
          ["A hypothesis can’t be falsified", "Rewrite it", "Engineer"],
          ["Disagreement on the top risks", "Escalate", "Tech lead"],
          ["Very few unknowns, or a well-understood problem", "Short list, no ranking workshop; move straight on", "Tech lead"],
          ["Two hypotheses contradict each other", "Keep both — the spike decides", "Engineer"],
          ["An unknown can only be answered in production", "Find the nearest safe proxy", "Engineer"],
          ["No real unknowns", "Skip to quality attributes and record why in the learning log", "Tech lead"],
        ] },
        { t: "figure", fig: { kind: "decide", start: "q1", nodes: [{ id: "q1", q: "Are there any real unknowns?", yes: "q2", no: "r1" }, { id: "r1", result: "Skip to quality attributes and record why in the learning log. Tech lead.", tone: "neutral" }, { id: "q2", q: "Very few unknowns, or a well-understood problem?", yes: "r2", no: "q3" }, { id: "r2", result: "Short list, no ranking workshop; move straight on. Tech lead.", tone: "good" }, { id: "q3", q: "Can every hypothesis be falsified?", yes: "q4", no: "r3" }, { id: "r3", result: "Rewrite it. Engineer.", tone: "neutral" }, { id: "q4", q: "Can each be answered without production?", yes: "q5", no: "r4" }, { id: "r4", result: "Find the nearest safe proxy: a masked sample, a test tenant, a load test against a copy. Engineer.", tone: "neutral" }, { id: "q5", q: "Does the team agree on the top three?", yes: "r6", no: "r5" }, { id: "r5", result: "Escalate. Tech lead decides.", tone: "neutral" }, { id: "r6", result: "Hand the list to 1.2.3 Set Quality Attributes & Success Metrics. Tech lead.", tone: "good" }] }, caption: "The routes out of Unknowns Ranked. If two hypotheses contradict each other, keep both — the spike decides." },
        { t: "p", text: "Some unknowns can only really be answered in production. Don’t wait for production — find the nearest safe proxy: a masked sample, a test tenant, a load test against a copy. And when two hypotheses contradict each other, resist the urge to pick one now. That’s what evidence is for." },
        { t: "figure", fig: { kind: "flow", steps: [{ label: "Q-## / A-##", sub: "open question or assumption", tone: "system" }, { label: "H-##", sub: "we believe… wrong if…", tone: "new" }, { label: "Rated", sub: "impact × uncertainty", tone: "human" }, { label: "Ranked", sub: "top three agreed", tone: "human" }, { label: "Test route", sub: "spike · measure · ask · docs", tone: "new" }] }, caption: "From scattered unknowns to ranked, testable hypotheses: scattered → written → rated → ranked → agreed." },
        { t: "good", items: ["Each hypothesis says what result would prove it wrong", "Each has impact and uncertainty rated, with a reason", "One unknown per hypothesis, each linked to its Q-## or A-##", "Each has a test route: spike, measure, ask or docs", "The riskiest three are agreed with the tech lead"] },
        { t: "h", text: "Before you move on" },
        { t: "checklist", title: "Unknowns Ranked", items: [
          "Every open question and low- or medium-confidence assumption is on the list",
          "Each is written as “We believe… We’re wrong if…”",
          "No hypothesis holds two unknowns",
          "Impact and uncertainty are rated for every one",
          "Each has a test route",
          "The tech lead has agreed the top three",
        ] },
        { t: "try", text: "Write three hypotheses for the order-intake case, each with “we’re wrong if…”, and rank them. Then do the same for your own project." },
      ],
    },
    /* ───────────────────────────── 1.2.3 ───────────────────────────── */
    {
      id: "discover.frame.quality", fid: "discover.frame.quality", code: "1.2.3", title: "Set Quality Attributes & Success Metrics", minutes: 11,
      blocks: [
        { t: "lead", text: "Ask anyone what the new system should be, and they’ll say fast, reliable and scalable. Those words compare nothing. This lesson turns them into numbers before any option is on the table." },
        { t: "tldr", items: [
          "Shortlist the ISO/IEC 25010 quality attributes that matter for this problem and rank them — at most three at the top.",
          "Write each top attribute as a scenario: when [stimulus], the system [response], measured as [number].",
          "Set technical success metrics: name, target, how and where it’s measured, and the attribute it proves.",
          "No “fast”, “reliable” or “scalable” without a number, a unit and a measurement method.",
          "The tech lead agrees the targets; the client confirms business-facing numbers: that’s the Targets Agreed gate.",
        ] },
        { t: "h", text: "Why it matters" },
        { t: "p", text: "This lesson makes “good enough” measurable *before* any option is compared, so the choice is judged against agreed targets instead of impressions." },
        { t: "p", text: "The order matters. If you set targets after you’ve seen the options, you’ll set them — without meaning to — so that your favourite passes. If you set them now, while every option is still hypothetical, the targets are honest. The concern this lesson guards against is **comparing options against vague goals**: a topic 1.5 decision that rests on whose adjectives were most persuasive." },
        { t: "figure", fig: { kind: "split", left: { title: "Targets set after seeing options", tone: "bad", items: ["Set so your favourite passes", "Decision rests on persuasive adjectives"] }, right: { title: "Targets set now", tone: "good", items: ["Every option still hypothetical", "Targets are honest"] } }, caption: "Why the order matters: the same targets, set at a different moment, judge the options very differently." },
        { t: "p", text: "The job: *help me know what the solution must be good at, in numbers, before I pick one.*" },
        { t: "pull", text: "A target you can’t measure is just a mood." },
        { t: "h", text: "Where it sits in Discover" },
        { t: "p", text: "You start this lesson once the hypotheses are ranked. It reads the system context pack — especially the volumes and limits you found in topic 1.1 — and the hypothesis list, and produces two artifacts: quality attribute priorities (QA-##) and technical success metrics (M-##). Both feed the spike plan in 1.2.4, and the metrics travel much further: topic 1.3 measures their baselines, topic 1.4 judges options against them, and later acts verify against them. Time-box it at two to four hours." },
        { t: "figure", fig: { kind: "flow", steps: [{ label: "QA-## and M-##", sub: "set in 1.2.3", tone: "new" }, { label: "Spike plan", sub: "1.2.4", tone: "new" }, { label: "Baselines measured", sub: "topic 1.3", tone: "human" }, { label: "Options judged", sub: "topic 1.4", tone: "human" }, { label: "Results verified", sub: "later acts", tone: "system" }] }, caption: "How far this topic’s metrics travel. A vague target here weakens every step after it." },
        { t: "table", caption: "Inputs, outputs and people", head: ["", "What"], rows: [
          ["In", "System context pack; Technical hypothesis list"],
          ["Out", "Quality attribute priorities (QA-##); Technical success metrics (M-##), linked to H-## and REQ-###"],
          ["Evidence", "Tech lead review notes"],
          ["A — accountable", "Tech lead: agrees the targets"],
          ["R — responsible", "Engineer: ranks, writes scenarios, sets metrics"],
          ["C — consulted", "Architect; Client contact (confirms business-facing numbers)"],
          ["I — informed", "Security"],
          ["Gate", "Targets Agreed"],
          ["Timebox", "2–4 hours"],
        ] },
        { t: "h", text: "Key ideas" },
        { t: "h3", text: "ISO/IEC 25010: a shared list" },
        { t: "p", text: "ISO/IEC 25010 is the international product quality model. It gives you a common vocabulary of quality characteristics so nobody has to invent one: functional suitability, performance efficiency, compatibility, usability, reliability, security, maintainability and portability. (The 2023 edition renames usability as *interaction capability* and portability as *flexibility*, and adds *safety*; the ideas are the same.) Each characteristic breaks down further — functional suitability includes *functional correctness*, performance efficiency includes *time behaviour* and *capacity*, reliability includes *availability* and *recoverability*." },
        { t: "figure", fig: { kind: "tree", root: "ISO/IEC 25010 quality model", children: [{ label: "Functional suitability", children: [{ label: "Functional correctness" }] }, { label: "Performance efficiency", children: [{ label: "Time behaviour" }, { label: "Capacity" }] }, { label: "Compatibility" }, { label: "Usability", text: "Interaction capability in the 2023 edition." }, { label: "Reliability", children: [{ label: "Availability" }, { label: "Recoverability" }] }, { label: "Security" }, { label: "Maintainability" }, { label: "Portability", text: "Flexibility in the 2023 edition." }] }, caption: "The shared vocabulary, with the sub-characteristics this topic uses. Treat it as a checklist: two or three will matter a lot here." },
        { t: "p", text: "Use it as a checklist, not a form. Most attributes matter a little; two or three matter a lot for *this* system. Your job is to say which, and in what order." },
        { t: "h3", text: "Quality attribute scenarios" },
        { t: "p", text: "A scenario makes a quality requirement testable. The full form has six parts: the *source* of a stimulus, the *stimulus* itself, the *environment* it happens in, the *artifact* affected, the system’s *response*, and the *response measure*. In practice you can write it in one sentence: *When* something happens, *the system* does something, *measured as* a number with a unit. That shape forces precision." },
        { t: "figure", fig: { kind: "hub", center: "Quality attribute scenario", items: [{ label: "Source", icon: "person", text: "Who or what produces the stimulus." }, { label: "Stimulus", icon: "sensors", text: "The event that happens." }, { label: "Environment", icon: "settings", text: "The conditions it happens in — at peak, when the API is down." }, { label: "Artifact", icon: "deployed_code", text: "The part of the system affected." }, { label: "Response", icon: "sync", text: "What the system does." }, { label: "Response measure", icon: "monitoring", text: "The number, with a unit, that says whether it was good enough." }] }, caption: "The full six-part form of a scenario. The one-sentence version keeps the stimulus, the response and the measure." },
        { t: "figure", fig: { kind: "knowledge", name: "Quality attribute scenarios" }, caption: "A quality attribute scenario: stimulus, response, and the measure that says whether it was good enough." },
        { t: "h3", text: "The utility tree and Attribute-Driven Design" },
        { t: "p", text: "A utility tree breaks “utility” — what makes the system good — into quality characteristics, refines each, and ends in concrete scenarios, each ranked by importance and by difficulty. It comes from the SEI’s Architecture Tradeoff Analysis Method. Attribute-Driven Design then uses the top-ranked scenarios to drive architecture: you design for the scenarios that matter most first. You won’t design anything in this topic, but the ranked scenarios you write are exactly what that design will start from." },
        { t: "figure", fig: { kind: "knowledge", name: "Utility tree" }, caption: "The utility tree: quality attributes broken down into ranked, measurable scenarios." },
        { t: "h3", text: "Goal–Question–Metric, and measuring what users feel" },
        { t: "p", text: "Goal–Question–Metric derives metrics top-down: state the goal, ask the questions that would show whether it’s met, then pick the metrics that answer them. It stops you measuring things simply because they’re easy to count. The principle *measure what users feel* points the same way: measure at the edge people touch — orders entered, lines right — not server internals. Where a metric can be checked automatically and repeatedly, it can later become a *fitness function*: an automated check that fails when the characteristic regresses." },
        { t: "figure", fig: { kind: "stack", layers: [{ label: "Goal", sub: "state what you want" }, { label: "Questions", sub: "what would show whether it’s met?" }, { label: "Metrics", sub: "what answers those questions", items: ["Measured at the edge people touch", "Orders entered, lines right", "Not server internals"] }, { label: "Fitness function", sub: "where a metric can be checked automatically and repeatedly" }] }, caption: "Goal–Question–Metric, top down. Metrics come last, so you don’t measure things just because they’re easy to count." },
        { t: "terms", items: [
          { term: "Quality attribute", def: "A property of the system that determines how well it does its job — reliability, performance efficiency, security and so on — taken from ISO/IEC 25010." },
          { term: "Scenario (QA-##)", def: "A quality attribute written as “when [stimulus], the system [response], measured as [number]”." },
          { term: "Success metric (M-##)", def: "A named measure with a baseline, a target, a measurement method, and the quality attribute it proves." },
          { term: "Baseline", def: "Today’s value of a metric. If you don’t have it yet, mark it “to measure” — topic 1.3 confirms it." },
          { term: "Provisional target", def: "A target set without full information, marked clearly to confirm once the baseline is measured." },
          { term: "Trade-off", def: "Where improving one attribute costs another — accuracy against latency, cost against resilience. Recorded, not hidden." },
        ] },
        { t: "h", text: "How to do it" },
        { t: "steps", items: [
          { title: "Rank the quality attributes", text: "Use the ISO/IEC 25010 list — functional suitability, performance efficiency, reliability, security, maintainability and the rest — and shortlist the ones that matter for this problem. Then rank them for *this* system, at most three at the top, with one line on why each matters here. Look back at the hypotheses: a high-impact hypothesis about volume is a strong hint that performance efficiency belongs near the top. A ranking where everything is “high” isn’t a ranking.", tip: "Ask “if we could only get one of these right, which would it be?” Then ask again for the second." },
          { title: "Write each as a measurable scenario", text: "*When* something happens, *the system* does something, *measured as* a number with a unit. Use the volumes and limits from your system context pack, not round numbers from the air. State latency and throughput as numbers at peak, not on an average day. For reliability, say what must never be lost and how quickly things recover. For security, state the expectation rather than assuming it’s understood.", tip: "Write the stimulus as something that will really happen — “at peak”, “when the API is down” — not an abstract load." },
          { title: "Set success metrics and targets", text: "For each attribute, define a metric: a name, a target, how and where it will be measured, and which quality attribute it proves. Fill in the baseline where you have one; where you don’t, write “to measure” — topic 1.3’s baseline work confirms it. Every target should say how it will be tested. If a target is set by regulation, it’s a hard constraint, and its owner confirms it.", tip: "If you can’t say where the data for a metric comes from, it isn’t a metric yet." },
          { title: "Decide: are the targets measurable?", text: "Check every target is a number with a unit and a measurement method, and flag any two that conflict. Anything vague is rewritten as a number. Conflicting targets go to the client — with the tech lead — because choosing between them is a business decision. When the tech lead agrees and the client has confirmed the business-facing numbers, the priorities and metrics go on to 1.2.4.", tip: "Read each target aloud with its unit. If it sounds like an adjective, it is one." },
        ] },
        { t: "figure", fig: { kind: "workflow", fid: "discover.frame.quality" }, caption: "Set Quality Targets — rank, write scenarios, set metrics, and the tech lead’s check that every target is measurable." },
        { t: "contrast", label: "A quality target", bad: { title: "An adjective", text: "“The system must be fast and reliable at peak.” Fast compared with what? Reliable meaning what? Nobody could ever say this target was missed." }, good: { title: "A scenario", text: "“At peak (≈160 orders/h), median e-mail-to-ERP time stays under 5 min.” A stimulus, a response, a number, a unit — and a way to check it from timestamps." } },
        { t: "figure", fig: { kind: "anatomy", parts: [{ text: "At peak (≈160 orders/h)", label: "When (stimulus)", note: "A load that will really happen, from the context pack." }, { text: ", median e-mail-to-ERP time", label: "What is measured", note: "Checkable from timestamps." }, { text: " stays under 5 min", label: "Number and unit" }, { text: "." }] }, caption: "The strong target, taken apart. Remove any one part and it slides back into an adjective." },
        { t: "callout", tone: "warn", title: "No adjectives without numbers", text: "No “fast”, “reliable” or “scalable” without a number, a unit and a way to measure it." },
        { t: "h", text: "The case: Northwind" },
        { t: "p", text: "Northwind’s ranking puts functional correctness first: wrong lines cost credit notes. Reliability is second, because a lost order is worse than a slow one. Performance efficiency is third, because the brief lands ahead of peak season." },
        { t: "figure", fig: { kind: "stack", layers: [{ label: "1 · Functional correctness", sub: "QA-1", items: ["Wrong lines cost credit notes"] }, { label: "2 · Reliability", sub: "QA-2", items: ["A lost order is worse than a slow one"] }, { label: "3 · Performance efficiency", sub: "QA-3", items: ["The brief lands ahead of peak season"] }] }, caption: "Northwind’s ranking, top first, each with its reason. Only three attributes are at the top, and they are in a firm order." },
        { t: "table", caption: "Northwind’s quality attribute priorities (REQ-014)", head: ["QA", "Attribute", "Rank", "Scenario: when… the system… measured as…", "Why it matters here"], rows: [
          ["QA-1", "Functional correctness", "1", "When a generated or scanned PDF order arrives, the system creates the ERP order with ≥ 98% of lines correct; anything below confidence goes to a clerk.", "Errors cost credit notes"],
          ["QA-2", "Reliability", "2", "When the ERP API is down, no order is lost; all are retried within 15 min of recovery.", "Lost orders are worse than slow ones"],
          ["QA-3", "Performance efficiency", "3", "At peak (≈160 orders/h) median e-mail-to-ERP time stays under 5 min.", "Peak season"],
        ] },
        { t: "callout", tone: "case", title: "Northwind", text: "QA-1 ≥ 98% of lines correct, QA-2 no order lost, QA-3 median under 5 min at peak; metrics M-1 to M-3 say how each is measured." },
        { t: "table", caption: "Northwind’s technical success metrics", head: ["M", "Metric", "Baseline (from 1.3.2)", "Target", "How measured", "Linked QA"], rows: [
          ["M-1", "Clerk minutes per e-mail order", "~14 min (to confirm)", "≤ 5 min", "ERP timestamps vs inbox received", "QA-3"],
          ["M-2", "Order lines entered wrongly", "3% (to confirm)", "≤ 1%", "Credit notes with “wrong line” reason", "QA-1"],
          ["M-3", "Orders lost or duplicated", "unknown", "0", "Inbox IDs reconciled with ERP orders daily", "QA-2"],
        ] },
        { t: "figure", fig: { kind: "bars", unit: "", rows: [{ label: "M-1 clerk minutes per order — today (to confirm)", value: 14, max: 15, note: "~14 min", tone: "bad" }, { label: "M-1 clerk minutes per order — target", value: 5, max: 15, note: "≤ 5 min", tone: "good" }, { label: "M-2 lines entered wrongly — today (to confirm), %", value: 3, max: 4, note: "3%", tone: "bad" }, { label: "M-2 lines entered wrongly — target, %", value: 1, max: 4, note: "≤ 1%", tone: "good" }] }, caption: "Northwind’s gap, today against target. The baselines are still marked “to confirm” — topic 1.3 measures them properly." },
        { t: "p", text: "Two details are worth copying. First, QA-1 already contains a trade-off: rather than demanding perfection, it sends anything below confidence to a clerk, accepting some manual work to protect correctness. Second, M-3’s baseline is honestly “unknown”. Nobody has counted lost orders yet, and pretending otherwise would make the target meaningless." },
        { t: "figure", fig: { kind: "template", id: "quality-attribute-priorities" }, caption: "Quality attribute priorities, written as scenarios." },
        { t: "h", text: "Working with your agent" },
        { t: "p", text: "An agent is a good scenario-writer: give it the shape and the context pack and it will produce a tidy first draft in minutes. It is also very comfortable writing “the system should respond quickly”. Your job is to push back on every scenario without a number and to make sure each measurement method is something you can actually run with the data you have." },
        { t: "prompt", title: "Rank and write scenarios", text: "From ISO/IEC 25010, shortlist the quality attributes that matter for this problem and rank them — at most three at the top — with one line on why each matters here. Use my system context pack and my ranked hypothesis list.\n\nThen write each top attribute as a scenario: “When [stimulus], the system [response], measured as [number]”. Use the volumes and limits from my system context pack, and state latency and throughput at peak." },
        { t: "p", text: "Check its answer: the ranking isn’t “everything high”; every scenario has a number and a unit; the numbers come from your pack, not invented round figures; reliability says what must never be lost; security is stated, not assumed." },
        { t: "prompt", title: "Set the metrics and check them", text: "Define the technical success metrics: name, target, how and where it will be measured, and which quality attribute it proves. Mark baselines as “to measure” where we don’t have them yet.\n\nThen check every target is a number with a unit and a measurement method, and flag any two targets that conflict." },
        { t: "p", text: "Check its answer: every “how measured” names a real data source you can reach; no baseline has been invented — if the agent filled one in, ask where it came from; conflicts are surfaced, not smoothed over. Conflicts go to the tech lead and the client, not into a compromise the agent chose." },
        { t: "figure", fig: { kind: "cycle", center: "Scenario review", steps: [{ label: "Agent drafts", text: "Scenarios and metrics from the context pack and hypotheses." }, { label: "Check number and unit", text: "Push back on every scenario without one." }, { label: "Check the source", text: "Numbers from the pack; no invented baselines; a reachable data source." }, { label: "Surface conflicts", text: "To the tech lead and the client, not into the agent’s compromise." }] }, caption: "Drafting scenarios with your agent is a loop: keep going round until every target is a number you can actually measure." },
        { t: "callout", tone: "agent", title: "With your agent", text: "Give your agent the context pack and hypotheses and ask for measurable scenarios in “when…, the system…, measured as…” form. Push back on every scenario without a number, and check each measurement method is something you can actually run." },
        { t: "h", text: "Common mistakes" },
        { t: "pitfalls", items: [
          { trap: "Every attribute rated high.", fix: "Force a ranking — at most three at the top." },
          { trap: "Targets without a measurement method.", fix: "Add how and where each is measured, and which data it comes from." },
          { trap: "Inventing a baseline to make the table look finished.", fix: "Write “to measure”. Topic 1.3 confirms baselines; a made-up one poisons every comparison after it." },
          { trap: "Measuring server internals because they’re easy to collect.", fix: "Measure what users feel — orders entered, lines right, time from e-mail to ERP." },
          { trap: "Hiding a conflict between two targets.", fix: "Record the trade-off, and take conflicts beyond the team to the tech lead and the client." },
        ] },
        { t: "h", text: "When it goes off the path" },
        { t: "p", text: "Attributes often pull against each other — accuracy against latency, cost against resilience. When they do, don’t hide it: record the trade-off. Option comparison in topic 1.5 depends on knowing which way you’d lean." },
        { t: "table", caption: "Routes out of the decision", head: ["Situation", "What you do", "Who decides"], rows: [
          ["Targets measurable and agreed", "Hand priorities and metrics to 1.2.4 Plan Time-boxed Discovery Spikes", "Tech lead"],
          ["Vague targets", "Rewrite as numbers", "Engineer"],
          ["Targets unknown", "Set a provisional target and mark it to confirm with the baseline", "Engineer"],
          ["Two attributes conflict", "Record the trade-off", "Engineer, with the architect"],
          ["Conflict beyond the team", "Escalate", "Tech lead and client"],
          ["Target set by regulation", "Treat it as a hard constraint, confirmed by its owner", "Owner of the regulation"],
          ["Small change", "One attribute, one metric", "Tech lead"],
          ["Nothing measurable", "Stop and say what’s missing; record it in the learning log", "Tech lead"],
        ] },
        { t: "figure", fig: { kind: "decide", start: "q1", nodes: [{ id: "q1", q: "Can anything be measured?", yes: "q2", no: "r1" }, { id: "r1", result: "Stop and say what’s missing; record it in the learning log. Tech lead.", tone: "bad" }, { id: "q2", q: "Is any target vague?", yes: "r2", no: "q3" }, { id: "r2", result: "Rewrite it as a number. Engineer.", tone: "neutral" }, { id: "q3", q: "Is any target unknown?", yes: "r3", no: "q4" }, { id: "r3", result: "Set a provisional target and mark it to confirm with the baseline. Engineer.", tone: "neutral" }, { id: "q4", q: "Do two attributes conflict?", yes: "q5", no: "r6" }, { id: "q5", q: "Can the team settle it?", yes: "r4", no: "r5" }, { id: "r4", result: "Record the trade-off. Engineer, with the architect.", tone: "neutral" }, { id: "r5", result: "Escalate. Tech lead and client decide.", tone: "neutral" }, { id: "r6", result: "Hand priorities and metrics to 1.2.4 Plan Time-boxed Discovery Spikes. Tech lead.", tone: "good" }] }, caption: "The routes out of Targets Agreed. A target set by regulation skips this: it’s a hard constraint, confirmed by its owner." },
        { t: "good", items: ["Every metric has a number, a unit and a measurement method", "Attributes are ranked, not all “high” — at most three at the top", "Every top attribute is a “when…, the system…, measured as…” scenario", "Baselines are real or honestly marked “to measure”", "Trade-offs between attributes are recorded", "The tech lead has agreed the targets and the client has confirmed the business-facing numbers"] },
        { t: "h", text: "Before you move on" },
        { t: "checklist", title: "Targets Agreed", items: [
          "Quality attributes are shortlisted from ISO/IEC 25010 and ranked",
          "Each top attribute is written as a measurable scenario",
          "Each metric has a target, a unit, a method and a linked QA",
          "Missing baselines are marked “to measure”",
          "Conflicts are recorded as trade-offs or escalated",
          "The tech lead has agreed the targets; the client has confirmed business-facing numbers",
        ] },
        { t: "try", text: "Write the reliability scenario for the order-intake case: when…, the system…, measured as…. Then do the same for your own project." },
      ],
    },
    /* ───────────────────────────── 1.2.4 ───────────────────────────── */
    {
      id: "discover.frame.spikes", fid: "discover.frame.spikes", code: "1.2.4", title: "Plan Time-boxed Discovery Spikes", minutes: 11,
      blocks: [
        { t: "lead", text: "A spike is a small experiment that answers one question. It isn’t a prototype of the product and it isn’t the first sprint in disguise." },
        { t: "tldr", items: [
          "Pick the ranked hypotheses that only an experiment can answer; answer the rest from docs, a measurement or an owner.",
          "Design the smallest throwaway test that could prove each one wrong — on masked or synthetic data, never production.",
          "Give each a timebox (a day or less unless justified) and a success signal written before anything runs.",
          "Assemble the framing pack: problem, ranked unknowns, quality targets, metrics and spike plan.",
          "The tech lead approves the plan at the Technical Framing Review. Spike code never goes to production.",
        ] },
        { t: "h", text: "Why it matters" },
        { t: "p", text: "This lesson turns the riskiest hypotheses into the smallest tests you can run in a fixed time, each with its success signal written down *before* it starts." },
        { t: "p", text: "Without a plan, spikes go wrong in two predictable ways. They grow: a one-day test of a library turns into a week of building a pipeline around it. And they get judged after the fact: you see 91%, decide that’s “pretty good actually”, and the hypothesis survives by moving the goalposts. The concerns this lesson guards against are **endless spiking** and **spike code shipped to production**." },
        { t: "figure", fig: { kind: "split", left: { title: "The spike grows", tone: "bad", items: ["A one-day test of a library", "Becomes a week building a pipeline around it"] }, right: { title: "Judged after the fact", tone: "bad", items: ["You see 91%", "Decide it’s “pretty good actually”", "The goalposts move"] } }, caption: "The two predictable ways spikes go wrong without a plan. A timebox stops the first; a signal written in advance stops the second." },
        { t: "p", text: "The job: *help me plan the smallest experiments that answer the questions that could sink this.*" },
        { t: "pull", text: "Write the success signal before you see the data. Afterwards, every result looks like a pass." },
        { t: "h", text: "Where it sits in Discover" },
        { t: "p", text: "This is the last lesson of the framing topic, and it closes the topic’s gate. It starts once the quality targets are agreed, reads the ranked hypothesis list, the quality attribute priorities and the success metrics, and produces two things: the spike plan, and the technical framing pack that bundles everything this topic made. Both hand on to 1.3 Investigate the Real Problem. Time-box it at one to two hours — you’re planning spikes here, not running them." },
        { t: "table", caption: "Inputs, outputs and people", head: ["", "What"], rows: [
          ["In", "Technical hypothesis list; Quality attribute priorities; Technical success metrics"],
          ["Out", "Spike plan (SPK-##, each linked to an H-##); Technical framing pack"],
          ["Evidence", "Tech lead review notes"],
          ["A — accountable", "Tech lead: approves the plan and its timeboxes"],
          ["R — responsible", "Engineer: picks, designs, time-boxes, assembles"],
          ["C — consulted", "Architect"],
          ["I — informed", "Client contact"],
          ["Gate", "Technical Framing Review"],
          ["Timebox", "1–2 hours"],
        ] },
        { t: "figure", fig: { kind: "context", center: { label: "Spike plan & framing pack", sub: "1.2.4" }, around: [{ label: "Technical hypothesis list", type: "store", dir: "in" }, { label: "Quality attribute priorities", type: "store", dir: "in" }, { label: "Technical success metrics", type: "store", dir: "in" }, { label: "Engineer", sub: "responsible", type: "person", link: "picks, designs, time-boxes, assembles", dir: "out" }, { label: "Tech lead", sub: "accountable", type: "person", link: "approves the plan and timeboxes", dir: "both" }, { label: "Architect", sub: "consulted", type: "person", dir: "both" }, { label: "Client contact", sub: "informed", type: "person", dir: "out" }, { label: "1.3 Investigate the Real Problem", type: "system", link: "receives both", dir: "out" }] }, caption: "Everything this topic made flows into this last lesson, and out again as one pack for investigation." },
        { t: "h", text: "Key ideas" },
        { t: "h3", text: "Spike and technical spike" },
        { t: "p", text: "A spike is a short, time-boxed piece of throwaway work that answers one specific technical question. You write the single question, set a strict timebox, build only enough to answer it, then record the answer and the decision — and discard the code. A *technical spike* is the engineering practice of doing exactly that for a feasibility question: agree the question and timebox, build the minimum, report the answer and what’s still unknown, throw the code away." },
        { t: "figure", fig: { kind: "knowledge", name: "Spike" }, caption: "A spike: one question, a timebox, a signal set in advance, and code you throw away." },
        { t: "h3", text: "Timebox" },
        { t: "p", text: "A timebox fixes the time and lets the scope flex. When the time runs out, you stop and look at what you learned — you don’t extend it because you’re “nearly there”. The default here is a day or less per spike, unless the tech lead agrees more. That cap is what makes endless spiking impossible: a spike that can’t fit isn’t a spike yet, it’s several." },
        { t: "h3", text: "Learn the most for the least" },
        { t: "p", text: "Rank questions by the uncertainty they remove divided by what they cost. Some hypotheses are expensive to spike and cheap to answer another way — a page of documentation, a measurement on data you already have, a phone call to the owner. Spikes are for the ones only an experiment can answer. This is the same instinct as Lean Product Discovery: the cheapest test that exposes the riskiest assumption." },
        { t: "figure", fig: { kind: "tree", root: "A ranked hypothesis", children: [{ label: "Spike", text: "Only when only an experiment can answer it." }, { label: "Docs", text: "A page of documentation." }, { label: "Measure", text: "A measurement on data you already have." }, { label: "Ask", text: "A phone call to the owner." }] }, caption: "Four ways to answer a hypothesis. Pick the cheapest one that removes the uncertainty; spikes are the expensive branch." },
        { t: "h3", text: "Walking skeleton — and why it isn’t a spike" },
        { t: "p", text: "A walking skeleton is the thinnest implementation that runs end to end through every major component, built to prove the path and then thickened slice by slice. It’s useful thinking for spike design — what’s the thinnest thing that would show this works? — but it’s a different animal. A skeleton is meant to last; a spike is meant to be thrown away. Don’t let a spike quietly become the skeleton." },
        { t: "figure", fig: { kind: "split", left: { title: "Spike", tone: "fact", items: ["Answers one question", "Time-boxed", "Meant to be thrown away"] }, right: { title: "Walking skeleton", tone: "good", items: ["Thinnest path end to end through every major component", "Thickened slice by slice", "Meant to last"] } }, caption: "Two thin things that look alike. Borrow the skeleton’s “thinnest thing” thinking for spike design, but never let a spike become the skeleton." },
        { t: "terms", items: [
          { term: "Spike (SPK-##)", def: "A throwaway, time-boxed experiment that answers one hypothesis, linked to its H-##." },
          { term: "Smallest test", def: "The least you could build or run that could prove the hypothesis wrong." },
          { term: "Success signal", def: "The result that counts as a pass, written into the plan before the spike runs." },
          { term: "Masked sample", def: "Real data with personal and sensitive fields removed or replaced, so it can be used safely outside production." },
          { term: "Synthetic data", def: "Data generated to look like the real thing in shape and volume, containing nothing real." },
          { term: "Technical framing pack", def: "Topic 1.2 in one place: the problem split, ranked hypotheses, quality priorities, success metrics and spike plan." },
        ] },
        { t: "h", text: "How to do it" },
        { t: "steps", items: [
          { title: "Pick the hypotheses that need a spike", text: "Go down the ranked list, starting at the top. For each, ask: can only an experiment answer this? Not every unknown needs one — some are answered by a document or a phone call, some by measuring data you already hold. For those, say how they’ll be answered instead: docs, a measurement, or asking an owner. Every top hypothesis leaves this step with either a spike or a written reason it needs none.", tip: "If a hypothesis can be answered from the docs, answer it now and update the list. That’s the cheapest spike there is." },
          { title: "Design the smallest test for each", text: "What’s the least you could build or run that could prove the hypothesis wrong? Name what to build or run, on which data, in which environment. Name test environments and trial accounts explicitly. Use masked or synthetic data only. For anything AI or ML, measure accuracy on your own samples, not the vendor’s demo. And no production systems, ever — the policy is never to spike against production.", tip: "Design to *disprove*. A test that can only confirm the hypothesis isn’t telling you anything." },
          { title: "Set the timebox and the success signal", text: "How long, and what result counts as a pass — decided now, not after you’ve seen the data. A day or less unless justified. The signal should map straight onto the hypothesis’s “we’re wrong if”: if the hypothesis says “wrong if accuracy is below 95%”, the signal says “≥ 95%”. Write it into the plan before anyone starts. Name an owner for each spike.", tip: "If the signal needs more than one sentence, the spike is probably answering more than one question." },
          { title: "Assemble the framing pack", text: "Bring this topic together: one paragraph each for the problem, the ranked unknowns, the quality targets and the spike plan, with links to the full documents — the problem split, hypotheses, quality priorities, metrics and spike plan. It should read as one frame, not five attachments. This is what topic 1.3 starts from, so write the paragraphs for someone who wasn’t in the room.", tip: "Read the pack top to bottom: does each part follow from the one before? If the spikes don’t test the top hypotheses, something has drifted." },
          { title: "Decide: is the spike plan approved?", text: "The tech lead reviews the plan: is every spike small, time-boxed, safe and tied to one hypothesis? Does anything touch production? If a spike is too big, split it. If it needs money or access — a paid service, credentials to a test tenant — the tech lead decides. If there’s genuinely nothing worth testing, stop framing and record why in the learning log. When the plan is approved and the pack is accepted, this topic is done.", tip: "Approval is for the plan, not the results. Nobody knows the results yet, and that’s the point." },
        ] },
        { t: "figure", fig: { kind: "workflow", fid: "discover.frame.spikes" }, caption: "Plan Time-boxed Discovery Spikes — pick, design, timebox, assemble, approve." },
        { t: "figure", fig: { kind: "hub", center: "Technical framing pack", items: [{ label: "The problem", icon: "description", text: "The problem / solution split, in one paragraph." }, { label: "Ranked unknowns", icon: "science", text: "The technical hypotheses, ranked." }, { label: "Quality targets", icon: "speed", text: "The quality attribute priorities." }, { label: "Success metrics", icon: "monitoring", text: "Each metric with its target and method." }, { label: "Spike plan", icon: "timer", text: "One row per spike, with its signal set in advance." }] }, caption: "This topic in one place: a paragraph per part, with links to the full documents. It should read as one frame, not five attachments." },
        { t: "contrast", label: "A spike", bad: { title: "A project in disguise", text: "“Spike: build an OCR pipeline and see how it goes.” No hypothesis, no timebox, no signal, and nothing stopping the code from shipping." }, good: { title: "One question, fixed time", text: "“SPK-1 tests H-01: run 2 OCR services over 200 masked inbox PDFs; compare to clerk-entered orders. Timebox 1 day. Pass: ≥ 95% of lines exact on generated, ≥ 85% on scans. Masked sample, vendor trials.”" } },
        { t: "figure", fig: { kind: "anatomy", parts: [{ text: "SPK-1 tests H-01", label: "One hypothesis" }, { text: ": run 2 OCR services over 200 masked inbox PDFs; compare to clerk-entered orders.", label: "Smallest test" }, { text: " Timebox 1 day.", label: "Timebox" }, { text: " Pass: ≥ 95% of lines exact on generated, ≥ 85% on scans.", label: "Success signal", note: "Written before anything runs; it mirrors H-01’s “wrong if”." }, { text: " Masked sample, vendor trials.", label: "Data / environment" }] }, caption: "A good spike, part by part. Remove any part and it drifts back towards “a project in disguise”." },
        { t: "callout", tone: "warn", title: "Spikes are throwaway", text: "No spike code goes to production. The moment spike code is “good enough to keep”, you’ve skipped design, review and tests without anyone deciding to." },
        { t: "h", text: "The case: Northwind" },
        { t: "p", text: "Northwind’s top two hypotheses both need an experiment. H-03, customer matching, has a different route: it can be answered by measuring the match rate on the inbox sample, so it doesn’t get a spike." },
        { t: "figure", fig: { kind: "funnel", stages: [{ label: "Ranked hypotheses", count: 3, items: ["H-01 OCR accuracy", "H-02 ERP throughput", "H-03 customer matching"] }, { label: "Need an experiment", count: 2, items: ["H-01", "H-02"] }, { label: "Spikes planned", count: 2, items: ["SPK-1", "SPK-2"] }] }, caption: "Northwind’s narrowing. H-03 drops out of the spike plan because measuring the match rate on the inbox sample answers it." },
        { t: "table", caption: "Northwind’s spike plan (REQ-014)", head: ["SPK", "Hypothesis", "Smallest test", "Timebox", "Success signal (set now)", "Data / environment", "Owner"], rows: [
          ["SPK-1", "H-01 OCR accuracy", "Run 2 OCR services over 200 masked inbox PDFs; compare to clerk-entered orders", "1 day", "≥ 95% of lines exact on generated, ≥ 85% on scans", "Masked sample, vendor trials", "Engineer"],
          ["SPK-2", "H-02 ERP throughput", "Script 1,000 synthetic orders into the ERP test tenant", "½ day", "≥ 160 orders/h sustained, no errors", "ERP test tenant", "Engineer"],
        ] },
        { t: "figure", fig: { kind: "bars", unit: "days", rows: [{ label: "SPK-1 OCR accuracy (H-01)", value: 1, max: 1, note: "1 day", tone: "neutral" }, { label: "SPK-2 ERP throughput (H-02)", value: 0.5, max: 1, note: "½ day", tone: "good" }] }, caption: "Each spike’s timebox against the default cap of a day. Both fit; neither needed the tech lead to agree more." },
        { t: "callout", tone: "case", title: "Northwind", text: "SPK-1: two OCR services on 200 masked PDFs in a day, signal ≥ 95%. SPK-2: 1,000 synthetic orders into the ERP test tenant in half a day." },
        { t: "p", text: "See how each spike answers to its hypothesis. H-01 says “wrong if line accuracy is below 95% on a 200-PDF sample”, and SPK-1 tests exactly that, on exactly that sample size, split by generated and scanned PDFs because Q-02 is still open. H-02 says “wrong if sustained throughput is below 160 an hour”, and SPK-2’s signal is that number. Both use trial accounts or a test tenant, both use masked or synthetic data, and neither touches the live ERP." },
        { t: "figure", fig: { kind: "template", id: "spike-plan" }, caption: "The spike plan — one row per spike, tied to its hypothesis, with its signal set in advance." },
        { t: "figure", fig: { kind: "template", id: "technical-framing-pack" }, caption: "The technical framing pack — topic 1.2 in one place, handed to investigation." },
        { t: "h", text: "Working with your agent" },
        { t: "p", text: "Agents are useful at both ends of a spike: designing the test now, and scaffolding the throwaway code when it runs. But they lean towards the polished version — error handling, configuration, a nice interface — none of which a spike needs. And an agent asked to set a success signal after seeing results will rationalise whatever it saw. So you cut the designs down, and you write the signal yourself." },
        { t: "prompt", title: "Pick and design", text: "From my ranked hypotheses, pick the ones a spike can answer. For the rest, say how they’ll be answered instead: docs, a measurement, or asking an owner.\n\nFor each spike, design the smallest throwaway test that could prove the hypothesis wrong — what to build or run, on which data and environment. Masked or synthetic data only. No production systems. Give each a timebox of a day or less unless you can justify more, and propose a success signal that matches the hypothesis’s “we’re wrong if”." },
        { t: "p", text: "Check its answer: every spike answers exactly one hypothesis; nothing names a production system or real customer data; each design is the *smallest* test, not a mini-product — cut it down if not; the proposed signal matches the “wrong if” in your hypothesis list. Then write the final signal into the plan yourself." },
        { t: "prompt", title: "Review as the tech lead would", text: "Review my spike plan as the tech lead would: is every spike small, time-boxed, safe and tied to one hypothesis? Does anything touch production? Which spike is most likely to overrun, and how would you split it?\n\nThen assemble my technical framing pack: one paragraph each for the problem, the ranked unknowns, the quality targets and the spike plan, with links to the full documents." },
        { t: "p", text: "Check its answer: the framing pack’s paragraphs say what the documents say — no new claims crept in; the problem paragraph still has no solution words; the review’s concerns are real ones you can act on. Then take the plan to the real tech lead." },
        { t: "figure", fig: { kind: "lanes", lanes: ["Agent", "You", "Tech lead"], steps: [{ lane: 0, label: "Picks and designs spikes", sub: "smallest test, timebox, proposed signal" }, { lane: 1, label: "Cut the designs down", sub: "agents propose the polished version", flag: "manual" }, { lane: 1, label: "Write the final signal yourself", sub: "before anything runs", flag: "manual" }, { lane: 0, label: "Reviews as the tech lead would", sub: "and assembles the framing pack" }, { lane: 1, label: "Check no new claims crept in", flag: "manual" }, { lane: 2, label: "Approves the plan", sub: "Technical Framing Review", flag: "ok" }] }, caption: "Planning spikes with your agent. The signal is yours to write; an agent setting it after the results will rationalise whatever it saw." },
        { t: "callout", tone: "agent", title: "With your agent", text: "Ask your agent to design the smallest test for each hypothesis and estimate how long it takes. Then cut it down further — agents tend to propose the polished version. Write the success signal yourself, before anything runs." },
        { t: "h", text: "Common mistakes" },
        { t: "pitfalls", items: [
          { trap: "A spike without a timebox.", fix: "Cap every spike at a day unless the tech lead agrees more." },
          { trap: "The success signal set after the result.", fix: "Write the signal into the plan before starting." },
          { trap: "One spike testing several hypotheses at once.", fix: "One hypothesis per spike. Split it." },
          { trap: "Spiking against production data or systems.", fix: "Use a masked sample or synthetic data, and a test tenant or trial account." },
          { trap: "Spike code that’s “good enough to keep”.", fix: "Spikes are throwaway. Record the answer; build it properly later, with design, review and tests." },
        ] },
        { t: "h", text: "When it goes off the path" },
        { t: "p", text: "Two failure modes to watch: **endless spiking** (if a spike won’t fit a timebox, split it) and spikes that need production data (use a masked sample or synthetic data instead)." },
        { t: "table", caption: "Routes out of the decision", head: ["Situation", "What you do", "Who decides"], rows: [
          ["Plan approved", "Hand the framing pack and spike plan to 1.3 Investigate the Real Problem", "Tech lead"],
          ["Spike too big", "Split it", "Engineer"],
          ["Hypothesis answerable from docs", "Answer it, no spike; record why", "Engineer"],
          ["Spike needs production data", "Use a masked sample or synthetic data", "Engineer"],
          ["Spike needs a paid service", "Use the free tier or a trial", "Engineer"],
          ["Spike needs money or access", "Escalate", "Tech lead"],
          ["Nothing worth testing", "Stop framing and record why in the learning log", "Tech lead"],
        ] },
        { t: "figure", fig: { kind: "decide", start: "q1", nodes: [{ id: "q1", q: "Is anything worth testing?", yes: "q2", no: "r1" }, { id: "r1", result: "Stop framing and record why in the learning log. Tech lead.", tone: "bad" }, { id: "q2", q: "Can the docs answer this hypothesis?", yes: "r2", no: "q3" }, { id: "r2", result: "Answer it, no spike; record why. Engineer.", tone: "good" }, { id: "q3", q: "Does the spike fit a timebox?", yes: "q4", no: "r3" }, { id: "r3", result: "Split it. Engineer.", tone: "neutral" }, { id: "q4", q: "Does it need production data?", yes: "r4", no: "q5" }, { id: "r4", result: "Use a masked sample or synthetic data. Engineer.", tone: "neutral" }, { id: "q5", q: "Does it need a paid service or access?", yes: "q6", no: "r7" }, { id: "q6", q: "Will a free tier or trial do?", yes: "r5", no: "r6" }, { id: "r5", result: "Use the free tier or a trial. Engineer.", tone: "neutral" }, { id: "r6", result: "Escalate: money or access. Tech lead decides.", tone: "neutral" }, { id: "r7", result: "Plan approved: hand the framing pack and spike plan to 1.3 Investigate the Real Problem. Tech lead.", tone: "good" }] }, caption: "Walk a spike through the review. Every “no” on the safe path has a route already written down, and only money or access goes up to the tech lead." },
        { t: "p", text: "The real failure is a spike that can’t be designed inside any timebox. That usually means the question is still too broad — go back to the hypothesis and split it — or that it isn’t a feasibility question at all, and belongs in the option research in topic 1.4." },
        { t: "figure", fig: { kind: "trace", from: "H", to: "SPK" }, caption: "This topic’s stretch of the trace chain: every spike links to a hypothesis, and every quality attribute to the hypotheses it answers." },
        { t: "good", items: ["Every spike answers one hypothesis", "Every spike has a timebox and a success signal set in advance", "Spike data is masked or synthetic; nothing touches production", "Every top hypothesis has a spike or a written reason it needs none", "The framing pack is assembled and approved"] },
        { t: "h", text: "Before you move on" },
        { t: "checklist", title: "Technical Framing Review", items: [
          "The problem has no solution words in it",
          "Every hypothesis is falsifiable and the top three are agreed",
          "Every quality target is a number with a unit and a method",
          "Every spike is tied to one hypothesis, with a timebox and a signal set in advance",
          "No spike touches production or real customer data",
          "The framing pack is assembled and accepted by the tech lead",
        ] },
        { t: "try", text: "Write SPK-1 for OCR accuracy: test, timebox, success signal and data. Then do the same for your own project." },
      ],
    },
  ],
};
